183	// --- Transcript flush sentinel ---
184	
185	// stopHookSentinel is the string that appears in Claude Code's hook_progress
186	// entry when the stop hook has been invoked, indicating the transcript is fully flushed.
187	const stopHookSentinel = "hooks claude-code stop"
188	
189	// waitForTranscriptFlush polls the transcript file for the stop hook sentinel.
190	// Falls back silently after a timeout.
191	func waitForTranscriptFlush(ctx context.Context, transcriptPath string, hookStartTime time.Time) {
192		const (
193			maxWait      = 3 * time.Second
194			pollInterval = 50 * time.Millisecond
195			tailBytes    = 4096
196			maxSkew      = 2 * time.Second
197		)
198	
199		logCtx := logging.WithComponent(ctx, "agent.claudecode")
200	
201		// Fast path: skip the poll loop when the sentinel can't possibly appear.
202		// - File doesn't exist: nothing to poll.
203		// - File is stale (unmodified for 2+ min): agent isn't running anymore.
204		//   This avoids 3s timeouts per stale "active" session (e.g., agent crashed
205		//   without firing stop hook).
206		const staleThreshold = 2 * time.Minute
207		info, err := os.Stat(transcriptPath)
208		if err != nil {
209			// Most likely the file doesn't exist; other errors (permission, etc.)
210			// would also prevent polling, so skip the wait either way.
211			return
212		}
213		fileAge := time.Since(info.ModTime())
214		if fileAge > staleThreshold {
215			logging.Debug(logCtx, "transcript file is stale, skipping sentinel wait",
216				slog.Duration("file_age", fileAge),
217			)
218			return
219		}
220	
221		deadline := time.Now().Add(maxWait)
222		for time.Now().Before(deadline) {
223			if checkStopSentinel(transcriptPath, tailBytes, hookStartTime, maxSkew) {
224				logging.Debug(logCtx, "transcript flush sentinel found",
225					slog.Duration("wait", time.Since(hookStartTime)),
226				)
227				return
228			}
229			time.Sleep(pollInterval)
230		}
231		logging.Warn(logCtx, "transcript flush sentinel not found within timeout, proceeding",
232			slog.Duration("timeout", maxWait),
233		)
234	}
235	
236	// checkStopSentinel reads the tail of the transcript file and looks for the sentinel.
237	func checkStopSentinel(path string, tailBytes int64, hookStartTime time.Time, maxSkew time.Duration) bool {
238		f, err := os.Open(path) //nolint:gosec // path comes from agent hook input
239		if err != nil {
240			return false
241		}
242		defer f.Close()
243	
244		info, err := f.Stat()
245		if err != nil {
246			return false
247		}
248		offset := info.Size() - tailBytes
249		if offset < 0 {
250			offset = 0
251		}
252		buf := make([]byte, info.Size()-offset)
253		if _, err := f.ReadAt(buf, offset); err != nil {
254			return false
255		}
256	
257		lines := strings.Split(string(buf), "\n")
258		for _, line := range lines {
259			line = strings.TrimSpace(line)
260			if line == "" || !strings.Contains(line, stopHookSentinel) {
261				continue
262			}
263	
264			var entry struct {
265				Timestamp string `json:"timestamp"`
266			}
267			if json.Unmarshal([]byte(line), &entry) != nil || entry.Timestamp == "" {
268				continue
269			}
270			ts, err := time.Parse(time.RFC3339Nano, entry.Timestamp)
271			if err != nil {
272				ts, err = time.Parse(time.RFC3339, entry.Timestamp)
273				if err != nil {
274					continue
275				}
276			}
277			// Validate timestamp is within acceptable range:
278			// - Not too far in the past (before hook started minus skew)
279			// - Not too far in the future (after hook started plus skew)
280			lowerBound := hookStartTime.Add(-maxSkew)
281			upperBound := hookStartTime.Add(maxSkew)
282			if ts.After(lowerBound) && ts.Before(upperBound) {
283				return true
284			}
285		}
286		return false
287	}
