517	func handleLifecycleTurnStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
518		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
519		logging.Info(logCtx, "turn-start",
520			slog.String("event", event.Type.String()),
521			slog.String("session_id", event.SessionID),
522			slog.String("session_ref", event.SessionRef),
523			slog.String("model", event.Model),
524		)
525	
526		sessionID := event.SessionID
527		if sessionID == "" {
528			return fmt.Errorf("no session_id in %s event", event.Type)
529		}
530		if err := validation.ValidateSessionID(sessionID); err != nil {
531			return fmt.Errorf("invalid %s event: %w", event.Type, err)
532		}
533	
534		// Fill model from hint file if the agent didn't provide it on this hook
535		if event.Model == "" {
536			if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
537				event.Model = hint
538				logging.Debug(logCtx, "loaded model from hint file",
539					slog.String("model", hint))
540			}
541		}
542	
543		// Capture pre-prompt state (including transcript position via TranscriptAnalyzer)
544		_, captureSpan := perf.Start(ctx, "capture_pre_prompt_state")
545		if err := CapturePrePromptState(ctx, ag, sessionID, event.SessionRef); err != nil {
546			captureSpan.RecordError(err)
547			captureSpan.End()
548			return err
549		}
550		captureSpan.End()
551	
552		// Append prompt to prompt.txt on filesystem so it's available for
553		// mid-turn commits (before SaveStep writes it to the shadow branch).
554		// Prompts are separated by "\n\n---\n\n" to support multiple turns.
555		if event.Prompt != "" {
556			sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
557			if sessionDirAbs, absErr := paths.AbsPath(ctx, sessionDir); absErr == nil {
558				if mkErr := os.MkdirAll(sessionDirAbs, 0o750); mkErr == nil {
559					promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
560					existing, readErr := os.ReadFile(promptPath) //nolint:gosec // session metadata path
561					var content string
562					if readErr == nil && len(existing) > 0 {
563						content = string(existing) + "\n\n---\n\n" + event.Prompt
564					} else {
565						content = event.Prompt
566					}
567					if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil { //nolint:gosec // path from internal metadata, not user input
568						logging.Warn(logCtx, "failed to write prompt.txt",
569							slog.String("error", writeErr.Error()))
570					}
571				}
572			}
573		}
574	
575		// Ensure strategy setup and initialize session
576		_, initSpan := perf.Start(ctx, "init_session")
577		if err := strategy.EnsureSetup(ctx); err != nil {
578			logging.Warn(logCtx, "failed to ensure strategy setup",
579				slog.String("error", err.Error()))
580		}
581	
582		strat := GetStrategy(ctx)
583		if err := strat.InitializeSession(ctx, sessionID, ag.Type(), event.SessionRef, event.Prompt, event.Model); err != nil {
584			logging.Warn(logCtx, "failed to initialize session state",
585				slog.String("error", err.Error()))
586		}
