20	// CalculateTokenUsage sums per-assistant-message token usage from a Pi JSONL
21	// transcript starting at the given line offset. Only assistant messages on
22	// the active conversation branch contribute to the totals — see
23	// pijsonl.ResolveActiveBranch for the rationale.
24	func (a *PiAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
25		usage := &agent.TokenUsage{}
26		err := pijsonl.ForEachActiveMessage(transcriptData, fromOffset, func(entry pijsonl.Entry) {
27			if entry.Message.Role != pijsonl.RoleAssistant || entry.Message.Usage == nil {
28				return
29			}
30			usage.InputTokens += entry.Message.Usage.Input
31			usage.OutputTokens += entry.Message.Usage.Output
32			usage.CacheReadTokens += entry.Message.Usage.CacheRead
33			usage.CacheCreationTokens += entry.Message.Usage.CacheWrite
34			usage.APICallCount++
35		})
36		if err != nil {
37			return usage, fmt.Errorf("calculate token usage: %w", err)
38		}
39		return usage, nil
40	}
