42	// ExtractModel returns the model identifier from the most recent assistant
43	// message on the active conversation branch. Pi records the model on every
44	// assistant message (message.model, e.g. "gpt-5.5") but never reports it through
45	// hooks, so the transcript is the only source. Using the most recent message
46	// reflects mid-session model changes. Returns "" when no active-branch assistant
47	// message carries a model.
48	func (a *PiAgent) ExtractModel(transcriptData []byte) (string, error) {
49		model := ""
50		err := pijsonl.ForEachActiveMessage(transcriptData, 0, func(entry pijsonl.Entry) {
51			if entry.Message.Role == pijsonl.RoleAssistant && entry.Message.Model != "" {
52				model = entry.Message.Model
53			}
54		})
55		if err != nil {
56			return model, fmt.Errorf("extract model: %w", err)
57		}
58		return model, nil
59	}
