61	// GetTranscriptPosition returns the JSONL line count of the file at path.
62	// Used by the strategy as the offset for incremental ExtractModifiedFiles
63	// calls. Missing files report 0 (consistent with Claude Code).
64	func (a *PiAgent) GetTranscriptPosition(path string) (int, error) {
65		if path == "" {
66			return 0, nil
67		}
68		//nolint:gosec // path from validated SessionRef set by lifecycle hooks
69		data, err := os.ReadFile(path)
70		if err != nil {
71			if os.IsNotExist(err) {
72				return 0, nil
73			}
74			return 0, fmt.Errorf("read pi transcript: %w", err)
75		}
76		return pijsonl.CountLines(data), nil
77	}
