79	// ExtractModifiedFilesFromOffset scans Pi assistant tool calls from startOffset
80	// onward and returns file paths touched by file-modifying tools (`write`,
81	// `edit`). Branch-aware: only counts entries on the active conversation
82	// branch.
83	func (a *PiAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) ([]string, int, error) {
84		if path == "" {
85			return nil, 0, nil
86		}
87		//nolint:gosec // path from validated SessionRef
88		data, err := os.ReadFile(path)
89		if err != nil {
90			return nil, 0, fmt.Errorf("read pi transcript: %w", err)
91		}
92	
93		totalLines := pijsonl.CountLines(data)
94		seen := make(map[string]bool)
95		var files []string
96	
97		err = pijsonl.ForEachActiveMessage(data, startOffset, func(entry pijsonl.Entry) {
98			if entry.Message.Role != pijsonl.RoleAssistant {
99				return
100			}
101			var items []pijsonl.ContentItem
102			if err := json.Unmarshal(entry.Message.Content, &items); err != nil {
103				return
104			}
105			for _, item := range items {
106				if item.Type != "toolCall" {
107					continue
108				}
109				if item.Name != "write" && item.Name != "edit" {
110					continue
111				}
112				var args struct {
113					Path string `json:"path"`
114				}
115				if err := json.Unmarshal(item.Arguments, &args); err != nil {
116					continue
117				}
118				if args.Path != "" && !seen[args.Path] {
119					seen[args.Path] = true
120					files = append(files, args.Path)
121				}
122			}
123		})
124		if err != nil {
125			return files, totalLines, fmt.Errorf("extract modified files: %w", err)
126		}
127		return files, totalLines, nil
128	}
129	
130	// ExtractPrompts returns user-message text from the transcript starting at
131	// the given line offset. Branch-aware (drops abandoned-branch prompts).
132	func (a *PiAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
133		if sessionRef == "" {
134			return nil, nil
135		}
136		//nolint:gosec // sessionRef from validated SessionRef
137		data, err := os.ReadFile(sessionRef)
138		if err != nil {
139			return nil, fmt.Errorf("read pi transcript: %w", err)
140		}
141	
142		var prompts []string
143		err = pijsonl.ForEachActiveMessage(data, fromOffset, func(entry pijsonl.Entry) {
144			if entry.Message.Role != pijsonl.RoleUser {
145				return
146			}
147			// User content can be either a plain string or an array of typed blocks.
148			if text := pijsonl.DecodeStringContent(entry.Message.Content); text != "" {
149				prompts = append(prompts, text)
150				return
151			}
152			var items []pijsonl.ContentItem
153			if err := json.Unmarshal(entry.Message.Content, &items); err != nil {
154				return
155			}
156			for _, item := range items {
157				if item.Type == pijsonl.ContentTypeText && item.Text != "" {
158					prompts = append(prompts, item.Text)
159				}
160			}
161		})
162		if err != nil {
163			return prompts, fmt.Errorf("extract prompts: %w", err)
164		}
165		return prompts, nil
166	}
