140	// CalculateTokenUsage calculates token usage from a Claude Code transcript.
141	// This is specific to Claude/Anthropic's API format where each assistant message
142	// contains a usage object with input_tokens, output_tokens, and cache tokens.
143	//
144	// Due to streaming, multiple transcript rows may share the same message.id.
145	// We deduplicate by taking the row with the highest output_tokens for each message.id.
146	func CalculateTokenUsage(transcript []TranscriptLine) *agent.TokenUsage {
147		// Map from message.id to the usage with highest output_tokens
148		usageByMessageID := make(map[string]messageUsage)
149	
150		for _, line := range transcript {
151			if line.Type != envelopeTypeAssistant {
152				continue
153			}
154	
155			var msg messageWithUsage
156			if err := json.Unmarshal(line.Message, &msg); err != nil {
157				continue
158			}
159	
160			if msg.ID == "" {
161				continue
162			}
163	
164			// Keep the entry with highest output_tokens (final streaming state)
165			existing, exists := usageByMessageID[msg.ID]
166			if !exists || msg.Usage.OutputTokens > existing.OutputTokens {
167				usageByMessageID[msg.ID] = msg.Usage
168			}
169		}
170	
171		// Sum up all unique messages
172		usage := &agent.TokenUsage{
173			APICallCount: len(usageByMessageID),
174		}
175		for _, u := range usageByMessageID {
176			usage.InputTokens += u.InputTokens
177			usage.CacheCreationTokens += u.CacheCreationInputTokens
178			usage.CacheReadTokens += u.CacheReadInputTokens
179			usage.OutputTokens += u.OutputTokens
180		}
181	
182		return usage
183	}
