200	// ExtractSpawnedAgentIDs extracts agent IDs from Task tool results in a transcript.
201	// When a Task tool completes, the tool_result contains "agentId: <id>" in its content.
202	// Returns a map of agentID -> toolUseID for all spawned agents.
203	func ExtractSpawnedAgentIDs(transcript []TranscriptLine) map[string]string {
204		agentIDs := make(map[string]string)
205	
206		for _, line := range transcript {
207			if line.Type != "user" {
208				continue
209			}
210	
211			// Parse as array of content blocks (tool results)
212			var contentBlocks []struct {
213				Type      string          `json:"type"`
214				ToolUseID string          `json:"tool_use_id"`
215				Content   json.RawMessage `json:"content"`
216			}
217	
218			var msg struct {
219				Content json.RawMessage `json:"content"`
220			}
221			if err := json.Unmarshal(line.Message, &msg); err != nil {
222				continue
223			}
224	
225			if err := json.Unmarshal(msg.Content, &contentBlocks); err != nil {
226				continue
227			}
228	
229			for _, block := range contentBlocks {
230				if block.Type != "tool_result" {
231					continue
232				}
233	
234				// Content can be a string or array of text blocks
235				var textContent string
236	
237				// Try as array of text blocks first
238				var textBlocks []struct {
239					Type string `json:"type"`
240					Text string `json:"text"`
241				}
242				if err := json.Unmarshal(block.Content, &textBlocks); err == nil {
243					var textContentSb361 strings.Builder
244					for _, tb := range textBlocks {
245						if tb.Type == "text" {
246							textContentSb361.WriteString(tb.Text + "\n")
247						}
248					}
249					textContent += textContentSb361.String()
250				} else {
251					// Try as plain string
252					var str string
253					if err := json.Unmarshal(block.Content, &str); err == nil {
254						textContent = str
255					}
256				}
257	
258				// Look for agentId in the text. Drop any ID that isn't path-safe:
259				// callers build agent-<id>.jsonl from it and read that file, so this
260				// is the choke point that keeps the path inside subagentsDir,
261				// independent of extractAgentIDFromText's character handling.
262				if agentID := extractAgentIDFromText(textContent); agentID != "" && validation.ValidateAgentID(agentID) == nil {
263					agentIDs[agentID] = block.ToolUseID
264				}
265			}
266		}
267	
268		return agentIDs
269	}
