271	// extractAgentIDFromText extracts an agent ID from text containing "agentId: <id>".
272	func extractAgentIDFromText(text string) string {
273		const prefix = "agentId: "
274		idx := strings.Index(text, prefix)
275		if idx == -1 {
276			return ""
277		}
278	
279		// Extract the ID (alphanumeric characters after the prefix)
280		start := idx + len(prefix)
281		end := start
282		for end < len(text) && (text[end] >= 'a' && text[end] <= 'z' ||
283			text[end] >= 'A' && text[end] <= 'Z' ||
284			text[end] >= '0' && text[end] <= '9') {
285			end++
286		}
287	
288		if end > start {
289			return text[start:end]
290		}
291		return ""
292	}
