383	func (c *ClaudeCodeAgent) CalculateTotalTokenUsage(transcriptData []byte, startLine int, subagentsDir string) (*agent.TokenUsage, error) {
384		if len(transcriptData) == 0 {
385			return &agent.TokenUsage{}, nil
386		}
387	
388		// Slice to the relevant portion and parse
389		sliced := transcript.SliceFromLine(transcriptData, startLine)
390		parsed, err := transcript.ParseFromBytes(sliced)
391		if err != nil {
392			return nil, fmt.Errorf("failed to parse transcript: %w", err)
393		}
394	
395		// Calculate token usage from parsed transcript
396		mainUsage := CalculateTokenUsage(parsed)
397	
398		if subagentsDir == "" {
399			return mainUsage, nil
400		}
401	
402		// Extract spawned agent IDs from the FULL transcript (startLine=0), not the
403		// sliced portion. A subagent spawned before this checkpoint's startLine can
404		// keep writing to its transcript in later turns; scanning only the slice
405		// would miss it and undercount subagent token usage (#329).
406		//
407		// PERF (considered, retained deliberately): this re-parses the full
408		// transcript in addition to the sliced parse above — two JSONL parses per
409		// call, growing with session length. A single-pass version was rejected as
410		// not worth the risk: ParseFromBytes silently drops malformed lines, so a
411		// parsed-entry index does not correspond to a raw line number and naively
412		// slicing the full parse at startLine would misattribute main-agent usage;
413		// doing it safely would mean threading raw-line numbers through the shared
414		// transcript parser used by every agent. A cheap line scan for the Task
415		// marker instead of a full parse would duplicate ExtractSpawnedAgentIDs'
416		// nested tool_result decoding. The common no-subagent case already avoids
417		// this cost entirely via the subagentsDir == "" short-circuit above.
418		fullParsed, err := transcript.ParseFromBytes(transcriptData)
419		if err != nil {
420			return nil, fmt.Errorf("failed to parse full transcript: %w", err)
421		}
422		agentIDs := ExtractSpawnedAgentIDs(fullParsed)
423	
424		// Calculate subagent token usage. This re-reads each subagent transcript from
425		// line 0 on every call, so mainUsage.SubagentTokens is a cumulative-since-
426		// session-start snapshot — see the CalculateTotalTokenUsage interface contract
427		// in cmd/entire/cli/agent for how callers must accumulate it.
428		if len(agentIDs) > 0 {
429			subagentUsage := &agent.TokenUsage{}
430			for agentID := range agentIDs {
431				agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
432				agentUsage, err := CalculateTokenUsageFromFile(agentPath, 0)
433				if err != nil {
434					// Agent transcript may not exist yet or may have been cleaned up
435					continue
436				}
437				subagentUsage.InputTokens += agentUsage.InputTokens
438				subagentUsage.CacheCreationTokens += agentUsage.CacheCreationTokens
439				subagentUsage.CacheReadTokens += agentUsage.CacheReadTokens
440				subagentUsage.OutputTokens += agentUsage.OutputTokens
441				subagentUsage.APICallCount += agentUsage.APICallCount
442			}
443			if subagentUsage.APICallCount > 0 {
444				mainUsage.SubagentTokens = subagentUsage
445			}
446		}
447	
448		return mainUsage, nil
449	}
