451	// ExtractAllModifiedFiles extracts files modified by both the main agent and
452	// any subagents spawned via the Task tool. It parses the main transcript bytes from
453	// startLine, collects modified files from the main agent, then reads each
454	// subagent's transcript from subagentsDir to collect their modified files too.
455	// The result is a deduplicated list of all modified file paths.
456	func (c *ClaudeCodeAgent) ExtractAllModifiedFiles(transcriptData []byte, startLine int, subagentsDir string) ([]string, error) {
457		if len(transcriptData) == 0 {
458			return nil, nil
459		}
460	
461		// Slice to the relevant portion and parse
462		sliced := transcript.SliceFromLine(transcriptData, startLine)
463		parsed, err := transcript.ParseFromBytes(sliced)
464		if err != nil {
465			return nil, fmt.Errorf("failed to parse transcript: %w", err)
466		}
467	
468		// Collect modified files from main agent
469		fileSet := make(map[string]bool)
470		var files []string
471		for _, f := range ExtractModifiedFiles(parsed) {
472			if !fileSet[f] {
473				fileSet[f] = true
474				files = append(files, f)
475			}
476		}
477	
478		if subagentsDir == "" {
479			return files, nil
480		}
481	
482		// Find spawned subagents from the FULL transcript (startLine=0): a subagent
483		// spawned before this checkpoint's startLine may keep modifying files in
484		// later turns, and scanning only the slice would miss it (#329). Main-agent
485		// file extraction above stays scoped to the slice.
486		//
487		// PERF: the second full-transcript parse is retained deliberately for the
488		// same reasons documented on CalculateTotalTokenUsage above; the common
489		// no-subagent case is short-circuited by the subagentsDir == "" guard.
490		fullParsed, err := transcript.ParseFromBytes(transcriptData)
491		if err != nil {
492			return nil, fmt.Errorf("failed to parse full transcript: %w", err)
493		}
494		agentIDs := ExtractSpawnedAgentIDs(fullParsed)
495		for agentID := range agentIDs {
496			agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
497			agentLines, agentErr := transcript.ParseFromFileAtLine(agentPath, 0)
498			if agentErr != nil {
499				// Subagent transcript may not exist yet or may have been cleaned up
500				continue
501			}
502			for _, f := range ExtractModifiedFiles(agentLines) {
503				if !fileSet[f] {
504					fileSet[f] = true
505					files = append(files, f)
506				}
507			}
508		}
509	
510		return files, nil
511	}
